def load_predeclaration(path: str | Path = DEFAULT_CONFIG) -> dict[str, Any]:
    try:
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ContinuousConvergenceReentryPredeclarationError(
            f"could not read predeclaration: {exc}"
        ) from exc
    if not isinstance(payload, dict):
        _fail("predeclaration root must be an object")
    return payload


def validate_predeclaration(payload: Mapping[str, Any]) -> str:
    expected = predeclaration_definition()
    if payload.get("schema_version") != EXPECTED_SCHEMA:
        _fail("schema_version changed")
    if payload.get("checkpoint_id") != EXPECTED_CHECKPOINT:
        _fail("checkpoint_id changed")
    if payload.get("strategy_id") != EXPECTED_STRATEGY:
        _fail("strategy_id changed")
    parent = payload.get("parent_checkpoint")
    if not isinstance(parent, Mapping):
        _fail("parent checkpoint block missing")
    if parent.get("checkpoint_commit") != EXPECTED_PARENT_CHECKPOINT_COMMIT:
        _fail("parent checkpoint commit changed")
    if parent.get("receipt_commit") != EXPECTED_PARENT_RECEIPT_COMMIT:
        _fail("parent receipt commit changed")
    retained = payload.get("retained_frozen_parents")
    if not isinstance(retained, Mapping):
        _fail("retained parent block missing")
    if retained.get("candidate_e_champion_final_fingerprint") != EXPECTED_CHAMPION_FINAL_FINGERPRINT:
        _fail("Champion-Final fingerprint changed")
    observed_fp = canonical_fingerprint(payload)
    if observed_fp != EXPECTED_PREDECLARATION_FINGERPRINT:
        _fail(f"canonical fingerprint changed: {observed_fp}")
    if payload.get("predeclaration_fingerprint") != EXPECTED_PREDECLARATION_FINGERPRINT:
        _fail("predeclaration fingerprint field changed")
    if dict(payload) != expected:
        _fail("predeclaration content differs from exact frozen definition")
    return EXPECTED_PREDECLARATION_FINGERPRINT
